function browser_excel_rows(string $field='parsed_excel_rows'): ?array {
    $raw=(string)($_POST[$field]??'');
    if($raw==='')return null;
    $rows=json_decode($raw,true,512,JSON_THROW_ON_ERROR);
    if(!is_array($rows))throw new RuntimeException('داده خوانده‌شده از Excel معتبر نیست.');
    if(count($rows)>20000)throw new RuntimeException('تعداد ردیف‌های Excel بیش از حد مجاز است.');
    return $rows;
}

function health_data(): array {
    $dbOk=false;$dbError=null;$migration='-';$counts=[];
    try{$pdo=Database::connection();$dbOk=(bool)$pdo->query('SELECT 1')->fetchColumn();$migration=Migrator::latest();foreach(['companies','panels','accounts','account_settings_imports','daily_reports','daily_report_rows'] as $t){try{$counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();}catch(Throwable){$counts[$t]=0;}}}
    catch(Throwable $e){$dbError=$e->getMessage();}
    $paths=['storage/logs','storage/tmp','storage/backups'];$write=[];foreach($paths as $p)$write[$p]=is_writable(base_path($p));
    $fonts=['Vazirmatn 400'=>is_file(base_path('assets/fonts/vazirmatn-400.woff2')),'Vazirmatn 700'=>is_file(base_path('assets/fonts/vazirmatn-700.woff2')),'IRANSans'=>is_file(base_path('assets/fonts/Iranian-Sans.ttf'))||is_file(base_path('assets/fonts/Iranian Sans.ttf'))];return ['db_ok'=>$dbOk,'db_error'=>$dbError,'migration'=>$migration,'paths'=>$write,'counts'=>$counts,'accounting'=>AccountingService::infrastructureStatus(),'extensions'=>['ZipArchive'=>class_exists('ZipArchive'),'SimpleXML'=>function_exists('simplexml_load_string')],'fonts'=>$fonts];
}

