<script>
(function(){
  const input=document.getElementById('accountLiveSearch');
  const list=document.getElementById('accountList');
  const count=document.getElementById('accountVisibleCount');
  const form=document.getElementById('accountSearchForm');
  if(!input||!list) return;
  const rows=[...list.querySelectorAll('.account-row')];
  const norm=v=>String(v||'').trim().toLocaleLowerCase('fa-IR')
    .replace(/[يى]/g,'ی').replace(/ك/g,'ک')
    .replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d))
    .replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
  const apply=()=>{
    const q=norm(input.value);
    let visible=0;
    rows.forEach(row=>{
      const hay=norm(row.dataset.accountSearch||row.textContent);
      const show=!q||hay.includes(q);
      row.hidden=!show;
      if(show) visible++;
    });
    if(count) count.textContent=visible.toLocaleString('fa-IR');
  };
  input.addEventListener('input',apply);
  input.addEventListener('search',apply);
  if(form) form.addEventListener('submit',e=>{e.preventDefault();apply();});
  apply();
})();
</script>

