const moneyFmt=v=>{const n=(Number(v)||0)/REPORT_MONEY_FACTOR;return n.toLocaleString(REPORT_MONEY_LOCALE,{maximumFractionDigits:0})};
const dollarFmt=v=>(Number(v)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function customerCalc(g){const t=g.rows.reduce((a,r)=>(a.received+=Number(r.received)||0,a.paid+=Number(r.paid)||0,a.commission+=Number(r.commission)||0,a),{received:0,paid:0,commission:0});t.net=t.received-t.paid;return t}
function customerText(g,t){const lines=[`حساب ${g.name}`,REPORT_SOURCE_LABEL,`مبالغ به ${REPORT_MONEY_UNIT}`];for(const r of g.rows){lines.push(`${r.display_name_snapshot||r.original_name_snapshot||r.source_username} — ${r.source_username}`);if(Number(r.member_win)<0)lines.push(`باخت: ${dollarFmt(Math.abs(Number(r.member_win)))} دلار | درصد مشتری: ${moneyFmt(r.commission)} | دریافتی: ${moneyFmt(r.received)}`);else if(Number(r.member_win)>0)lines.push(`برد: ${dollarFmt(r.member_win)} دلار | پرداختی: ${moneyFmt(r.paid)}`);else lines.push('برد و باخت: صفر')}lines.push(`جمع دریافتی: ${moneyFmt(t.received)}`,`جمع پرداختی: ${moneyFmt(t.paid)}`,`درصد مشتری: ${moneyFmt(t.commission)}`,(t.net>0?'دریافت از مشتری: ':t.net<0?'پرداخت به مشتری: ':'تسویه: ')+moneyFmt(Math.abs(t.net)));return lines.join('\n')}
function openReportCustomer(id){const g=reportCustomerGroups[id];if(!g)return;activeReportCustomer=g;const t=customerCalc(g);document.getElementById('reportCustomerTitle').textContent='حساب '+g.name;document.getElementById('reportCustomerReportLabel').textContent=REPORT_SOURCE_LABEL;document.getElementById('reportCustomerUnit').textContent=REPORT_MONEY_UNIT+(REPORT_MONEY_FACTOR===1000?'؛ سه صفر حذف شده است':REPORT_MONEY_FACTOR===10000?'؛ چهار صفر حذف شده است':'');const body=document.getElementById('reportCustomerRows');body.innerHTML=g.rows.map(r=>`<tr><td class="name-cell">${htmlEscape(r.display_name_snapshot||r.original_name_snapshot||r.source_username)}</td><td class="username-cell" dir="ltr">${htmlEscape(r.source_username)}</td><td class="comm-cell">${moneyFmt(r.commission)}</td><td>${Number(r.member_win)<0?dollarFmt(Math.abs(Number(r.member_win))):''}</td><td class="recv-cell">${moneyFmt(r.received)}</td><td>${Number(r.member_win)>0?dollarFmt(r.member_win):''}</td><td class="pay-cell">${moneyFmt(r.paid)}</td></tr>`).join('');document.getElementById('reportCustomerTotals').innerHTML=`<div class="pay-cell"><span>جمع پرداختی</span><b>${moneyFmt(t.paid)}</b></div><div class="comm-cell"><span>درصد مشتری</span><b>${moneyFmt(t.commission)}</b></div><div class="recv-cell"><span>جمع دریافتی</span><b>${moneyFmt(t.received)}</b></div>`;const bal=document.getElementById('reportCustomerBalance');bal.className='customer-reference-balance '+(t.net>0?'recv-cell':t.net<0?'pay-cell':'comm-cell');bal.innerHTML=`<b>${t.net>0?'دریافت از مشتری':t.net<0?'پرداخت به مشتری':'تسویه'}: ${moneyFmt(Math.abs(t.net))}</b>`;document.getElementById('reportCustomerFallback').classList.add('hidden');document.getElementById('reportCustomerShareStatus').textContent='در حال آماده‌سازی عکس…';openAppDialog('reportCustomerDialog');requestAnimationFrame(()=>buildReportCustomerImage(g,t));}
function htmlEscape(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function createHiResCanvas(width,height,scale=2){const canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);const ctx=canvas.getContext('2d');ctx.setTransform(scale,0,0,scale,0,0);ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);return {canvas,ctx,scale}}
async function canvasToPngBlob(canvas){return SvoImage617.encode(canvas,{type:'png'})}
async function buildReportCustomerImage(g,t){if(document.fonts)await document.fonts.ready;const w=1680,rowH=86,top=182,h=470+g.rows.length*rowH,{canvas:c,ctx:x}=createHiResCanvas(w,h,2.2);x.direction='rtl';x.textAlign='center';x.textBaseline='middle';const txt=(value,cx,cy,width,font=22,color='#000',dir='rtl',weight=700)=>{x.font=`${weight} ${font}px Vazirmatn, Tahoma, Arial, sans-serif`;x.fillStyle=color;x.direction=dir;x.fillText(String(value),cx,cy,width-12)};txt('حساب '+g.name,w/2,52,w-80,40,'#111','rtl',900);txt(REPORT_SOURCE_LABEL,w/2,101,w-80,21,'#555','ltr',700);txt(`مبالغ به ${REPORT_MONEY_UNIT}${REPORT_MONEY_FACTOR===1000?'؛ سه صفر حذف شده است':REPORT_MONEY_FACTOR===10000?'؛ چهار صفر حذف شده است':''}`,w/2,138,w-80,24,'#111','rtl',700);const widths=[332,252,182,182,182,182,182],starts=[];let right=w-20;for(const ww of widths){right-=ww;starts.push(right)}const box=(left,yy,width,height,color,value,font=22,ink='#000',dir='rtl',weight=700)=>{x.fillStyle=color;x.fillRect(left,yy,width,height);x.strokeStyle='#222';x.lineWidth=1.6;x.strokeRect(left,yy,width,height);txt(value,left+width/2,yy+height/2,width,font,ink,dir,weight)};box(starts[1],top,widths[0]+widths[1],54,'#fff','مشخصات مشتری',28);box(starts[4],top,widths[2]+widths[3]+widths[4],54,'#fff','دریافتی (باخت مشتری)',28);box(starts[6],top,widths[5]+widths[6],54,'#fff','پرداختی (برد مشتری)',28);['نام مشتری','نام کاربری','درصد مشتری','به دلار','به تومان','به دلار','به تومان'].forEach((v,i)=>box(starts[i],top+54,widths[i],54,'#fff',v,22));g.rows.forEach((r,ri)=>{const vals=[r.display_name_snapshot||r.original_name_snapshot||r.source_username,r.source_username,moneyFmt(r.commission),Number(r.member_win)<0?dollarFmt(Math.abs(Number(r.member_win))):'',moneyFmt(r.received),Number(r.member_win)>0?dollarFmt(r.member_win):'',moneyFmt(r.paid)];vals.forEach((v,i)=>box(starts[i],top+108+ri*rowH,widths[i],rowH,i===2?REPORT_COLORS.comm:i===4?REPORT_COLORS.recv:i===6?REPORT_COLORS.pay:'#fff',v,i===0?23:i===1?20:25,'#000',i===1||i===3||i===5?'ltr':'rtl',i===0?800:700))});const y=top+120+g.rows.length*rowH;box(16,y,520,58,REPORT_COLORS.pay,'جمع پرداختی: '+moneyFmt(t.paid),24);box(548,y,520,58,REPORT_COLORS.comm,'درصد مشتری: '+moneyFmt(t.commission),24);box(1080,y,w-1096,58,REPORT_COLORS.recv,'جمع دریافتی: '+moneyFmt(t.received),24);box(16,y+60,w-32,78,t.net>0?REPORT_COLORS.recv:t.net<0?REPORT_COLORS.pay:REPORT_COLORS.comm,(t.net>0?'دریافت از مشتری: ':t.net<0?'پرداخت به مشتری: ':'تسویه: ')+moneyFmt(Math.abs(t.net)),32,'#000','rtl',900);const blob=await canvasToPngBlob(c);activeCustomerBlob=blob;if(activeCustomerUrl)URL.revokeObjectURL(activeCustomerUrl);activeCustomerUrl=URL.createObjectURL(blob);const img=document.getElementById('reportCustomerImage');img.src=activeCustomerUrl;const dl=document.getElementById('reportCustomerDownload');dl.href=activeCustomerUrl;dl.download='hesab-'+String(g.rows[0]?.source_username||'customer').replace(/[^a-zA-Z0-9_-]/g,'')+'.png';const fdl=document.getElementById('reportCustomerFallbackDownload');fdl.href=activeCustomerUrl;fdl.download=dl.download;document.getElementById('reportCustomerShareStatus').textContent='عکس آماده است.';}
async function copyReportCustomer622(){try{if(!activeCustomerBlob)throw Error('ابتدا عکس را بساز.');await SvoImage617.copyImage(()=>activeCustomerBlob,'customer.png');svoCopyToast('تصویر کپی شد.')}catch(e){appAlert(e.message)}}
function shareReportCustomer(target){if(!activeReportCustomer)return;const g=activeReportCustomer;if(!activeCustomerBlob){const status=document.getElementById('reportCustomerShareStatus');if(status)status.textContent='عکس هنوز آماده نیست؛ پس از نمایش کامل عکس دوباره «اشتراک عکس» را بزن.';return}const file=new File([activeCustomerBlob],document.getElementById('reportCustomerDownload').download||'customer-account.png',{type:'image/png'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){try{navigator.share({files:[file],title:'حساب '+g.name}).catch(e=>{if(e.name!=='AbortError')showReportCustomerFallback(customerText(g,customerCalc(g)),target)});return}catch(e){}}showReportCustomerFallback(customerText(g,customerCalc(g)),target)}
function showReportCustomerFallback(text,target){const box=document.getElementById('reportCustomerFallback');if(box)box.classList.remove('hidden');const dl=document.getElementById('reportCustomerFallbackDownload'),src=document.getElementById('reportCustomerDownload');if(dl&&src){dl.href=src.href;dl.download=src.download}const status=document.getElementById('reportCustomerShareStatus');if(status)status.textContent='اشتراک مستقیم فایل در این مرورگر انجام نشد. «دریافت عکس برای پیوست» را بزن و PNG را در تلگرام یا واتساپ به صورت فایل/Document ارسال کن تا فشرده نشود.'}
async function copyReportCustomerText(){if(!activeReportCustomer)return;const text=customerText(activeReportCustomer,customerCalc(activeReportCustomer));try{await navigator.clipboard.writeText(text);document.getElementById('reportCustomerShareStatus').textContent='متن حساب کپی شد.'}catch(e){const a=document.getElementById('reportCustomerFallbackText');a.value=text;a.classList.remove('hidden');a.select();document.getElementById('reportCustomerShareStatus').textContent='متن را از کادر انتخاب و کپی کن.'}}
const REPORT_SUMMARY_DATA=<?=json_encode(['title'=>$summaryTitle,'date'=>$summaryDate,'unit'=>SettingsService::moneyUnit($uiSettings),'recv'=>$summaryRecv,'pay'=>$summaryPay,'total_received'=>(float)$savedReport['total_received'],'total_paid'=>(float)$savedReport['total_paid'],'net'=>$summaryNet,'colors'=>$summaryColors,'factor'=>SettingsService::scaleFactor($uiSettings),'locale'=>$uiSettings['digit_mode']==='fa'?'fa-IR':'en-US'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
let reportSummaryBlob=null,reportSummaryUrl=null;
const summaryFmt=n=>(Number(n||0)/REPORT_SUMMARY_DATA.factor).toLocaleString(REPORT_SUMMARY_DATA.locale,{maximumFractionDigits:0});
function summaryText(){return [REPORT_SUMMARY_DATA.title,REPORT_SUMMARY_DATA.date,`جمع دریافتی: ${summaryFmt(REPORT_SUMMARY_DATA.total_received)}`,`جمع پرداختی: ${summaryFmt(REPORT_SUMMARY_DATA.total_paid)}`,`${REPORT_SUMMARY_DATA.net>0?'برد سایت':REPORT_SUMMARY_DATA.net<0?'باخت سایت':'تسویه'}: ${summaryFmt(Math.abs(REPORT_SUMMARY_DATA.net))}`].join('\n')}
function openReportSummary(){document.getElementById('reportSummaryFallback').classList.add('hidden');document.getElementById('reportSummaryShareStatus').textContent='در حال آماده‌سازی عکس…';openAppDialog('reportSummaryDialog');requestAnimationFrame(()=>buildReportSummaryImage())}
async function buildReportSummaryImage(){if(document.fonts)await document.fonts.ready;const D=REPORT_SUMMARY_DATA,rows=Math.max(D.recv.length,D.pay.length,1),w=1500,top=186,rowH=66,tableTop=top,totalTop=tableTop+102+rows*rowH+52,h=totalTop+214,{canvas:c,ctx:x}=createHiResCanvas(w,h,2.2);x.direction='rtl';x.textAlign='center';x.textBaseline='middle';const selectedFont=getComputedStyle(document.getElementById('reportSummaryDialog')).fontFamily||'Vazirmatn,Tahoma,Arial,sans-serif';const text=(t,cx,cy,max,font=24,weight=800)=>{x.fillStyle='#111';x.font=`${weight} ${font}px ${selectedFont}`;x.fillText(String(t),cx,cy,max)};text(D.title,w/2,52,w-60,46,900);text(D.date,w/2,112,w-60,32,800);text('مبالغ به '+D.unit,w/2,154,w-60,22,700);const gap=70,pad=34,colW=(w-gap-pad*2)/2;function box(left,y,width,height,color,label,font=23,weight=800){x.fillStyle=color;x.fillRect(left,y,width,height);x.strokeStyle='#111';x.lineWidth=1.8;x.strokeRect(left,y,width,height);text(label,left+width/2,y+height/2,width-14,font,weight)}function drawPanel(left,color,title,items){box(left,tableTop,colW,54,color,title,30,900);box(left,tableTop+54,colW/2,48,color,'مبلغ',22,800);box(left+colW/2,tableTop+54,colW/2,48,color,'نام مشتری',22,800);for(let i=0;i<rows;i++){const it=items[i];const fill=it?color:'#fff';box(left,tableTop+102+i*rowH,colW/2,rowH,fill,it?summaryFmt(it.amount):'',27,900);box(left+colW/2,tableTop+102+i*rowH,colW/2,rowH,fill,it?it.name:'',23,800)}}drawPanel(pad,D.colors.pay,'پرداختی',D.pay);drawPanel(pad+colW+gap,D.colors.recv,'دریافتی',D.recv);const tw=700;box(pad,totalTop,tw/2,60,D.colors.recv,summaryFmt(D.total_received),30,900);box(pad+tw/2,totalTop,tw/2,60,D.colors.recv,'جمع دریافتی',26,800);box(pad,totalTop+60,tw/2,60,D.colors.pay,summaryFmt(D.total_paid),30,900);box(pad+tw/2,totalTop+60,tw/2,60,D.colors.pay,'جمع پرداختی',26,800);box(pad,totalTop+120,tw/2,72,D.colors.result,summaryFmt(Math.abs(D.net)),32,900);box(pad+tw/2,totalTop+120,tw/2,72,D.colors.result,D.net>0?'برد سایت':D.net<0?'باخت سایت':'تسویه',30,900);const blob=await canvasToPngBlob(c);reportSummaryBlob=blob;if(reportSummaryUrl)URL.revokeObjectURL(reportSummaryUrl);reportSummaryUrl=URL.createObjectURL(blob);const img=document.getElementById('reportSummaryImage');img.src=reportSummaryUrl;const dl=document.getElementById('reportSummaryDownload');dl.href=reportSummaryUrl;dl.download='accounting-summary-'+REPORT_DISPLAY_DATE.replace(/[^0-9۰-۹_-]/g,'-')+'.png';const fdl=document.getElementById('reportSummaryFallbackDownload');fdl.href=reportSummaryUrl;fdl.download=dl.download;document.getElementById('reportSummaryShareStatus').textContent='عکس آماده است.';return blob}
async function copyReportSummary622(){try{if(!reportSummaryBlob)throw Error('ابتدا عکس را بساز.');await SvoImage617.copyImage(()=>reportSummaryBlob,'summary.png');svoCopyToast('تصویر کپی شد.')}catch(e){appAlert(e.message)}}
function shareReportSummary(target){if(!reportSummaryBlob){const status=document.getElementById('reportSummaryShareStatus');if(status)status.textContent='تصویر خلاصه هنوز آماده نیست؛ پس از آماده‌شدن دوباره اشتراک را بزن.';return}const file=new File([reportSummaryBlob],document.getElementById('reportSummaryDownload').download||'report-summary.png',{type:'image/png'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){try{navigator.share({files:[file],title:REPORT_SUMMARY_DATA.title}).catch(e=>{if(e.name!=='AbortError')showImageOnlyFallback('reportSummaryFallback','reportSummaryFallbackDownload',document.getElementById('reportSummaryDownload').href,'reportSummaryShareStatus')});return}catch(e){}}showImageOnlyFallback('reportSummaryFallback','reportSummaryFallbackDownload',document.getElementById('reportSummaryDownload').href,'reportSummaryShareStatus')}
function showImageOnlyFallback(boxId,downloadId,url,statusId){const box=document.getElementById(boxId),dl=document.getElementById(downloadId),status=document.getElementById(statusId);if(box)box.classList.remove('hidden');if(dl&&url){dl.href=url;dl.download='accounting-summary.png'}if(status)status.textContent='اشتراک مستقیم فایل ممکن نیست؛ عکس باکیفیت را دریافت و در پیام‌رسان به‌صورت فایل ارسال کن.'}
async function printReportSummary(){try{const blob=reportSummaryBlob||await buildReportSummaryImage();if(!blob)throw Error('تصویر خلاصه آماده نشد.');const url=URL.createObjectURL(blob);const frame=document.createElement('iframe');frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;width:1px;height:1px;right:-9999px;bottom:-9999px;border:0;opacity:0;pointer-events:none';document.body.appendChild(frame);const doc=frame.contentDocument;doc.open();doc.write(`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>خلاصه گزارش</title><style>@page{size:A4 landscape;margin:4mm}html,body{width:100%;height:100%;margin:0;padding:0;background:#fff;overflow:hidden}body{display:flex;align-items:center;justify-content:center}img{display:block;max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;-webkit-print-color-adjust:exact;print-color-adjust:exact}</style></head><body><img src="${url}"></body></html>`);doc.close();const img=doc.querySelector('img');await new Promise(resolve=>{if(img.complete)resolve();else{img.onload=resolve;img.onerror=resolve}});const cleanup=()=>{setTimeout(()=>{URL.revokeObjectURL(url);frame.remove()},250)};frame.contentWindow.addEventListener('afterprint',cleanup,{once:true});frame.contentWindow.focus();frame.contentWindow.print();setTimeout(cleanup,15000)}catch(e){appAlert(e?.message||'ساخت PDF انجام نشد.')}}
</script>
