<dialog id="rowEditor" class="app-dialog"><div class="dialog-card"><div class="dialog-head"><div><b id="rowEditorTitle">ویرایش ردیف</b><small>هر تغییر فقط Preview است؛ سرور هنگام ثبت نهایی دوباره محاسبه می‌کند.</small></div><button class="ghost icon-btn" type="button" onclick="closeAppDialog('rowEditor')">×</button></div><div class="form-grid"><label>Username<input id="editUsername" dir="ltr"></label><label>نام نمایشی<input id="editName"></label><label>وضعیت حساب<select id="editOutcome"><option value="loss">بازنده / دریافتی</option><option value="win">برنده / پرداختی</option><option value="zero">صفر</option></select></label><label>مبلغ دلاری<input id="editAmount" inputmode="decimal"></label><label>نرخ<input id="editRate" inputmode="decimal"></label><label>درصد مشتری<input id="editPct" inputmode="decimal"></label><label>پنل برای Username جدید<select id="editPanel"><option value="">بدون پنل / فقط همین گزارش</option><?php foreach($entryPanels as $p):?><option value="<?=e($p['id'])?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label class="toggle-line"><input type="checkbox" id="editRegister"> ثبت کنترل‌شده این Username در پنل انتخابی</label></div><div class="final-actions"><button class="primary" type="button" id="saveRowBtn">ذخیره ردیف</button><button class="danger" type="button" id="deleteRowBtn">حذف ردیف</button></div></div></dialog>
<dialog id="usdExceptionDialog" class="app-dialog usd-exception-dialog" aria-labelledby="usdExceptionTitle"><div class="dialog-card usd-exception-card"><div class="dialog-head"><b id="usdExceptionTitle">ثبت استثنایی تراز دلاری</b><button type="button" class="ghost icon-btn" aria-label="بستن" onclick="closeAppDialog('usdExceptionDialog')">×</button></div><div class="notice bad usd-exception-alert" id="usdExceptionDetails">اختلاف تراز دلاری تأیید نشده است.</div><div class="usd-exception-field"><label for="usdExceptionReason">علت دقیق مغایرت <span class="usd-exception-required">(حداقل ۸ نویسه)</span></label><textarea id="usdExceptionReason" rows="4" maxlength="2000" aria-describedby="usdExceptionHint" placeholder="مثلاً: اختلاف ناشی از اصلاح دستی مبلغ گزارش سایت مادر…"></textarea><p class="usd-exception-hint" id="usdExceptionHint">این توضیح در سابقه گزارش ذخیره می‌شود و هنگام تسویه قابل مشاهده خواهد بود.</p></div><div class="final-actions usd-exception-actions"><button class="ghost" type="button" onclick="closeAppDialog('usdExceptionDialog')">انصراف</button><button class="primary" type="button" id="usdExceptionConfirm">تأیید و ثبت استثنایی</button></div></div></dialog>
<dialog id="unknownResolver" class="app-dialog"><div class="dialog-card"><div class="dialog-head"><div><b>تعیین تکلیف Usernameهای ناشناخته</b><small>این تصمیم اجباری است. بدون آن گزارش ثبت نمی‌شود.</small></div><button class="ghost icon-btn" type="button" onclick="closeAppDialog('unknownResolver')">×</button></div><div id="unknownList" class="unknown-list"></div><label>پنل این گزارش<select id="unknownPanel"><option value="">انتخاب پنل…</option><?php foreach($entryPanels as $p):?><option value="<?=e($p['id'])?>" <?=((int)($draft['panel_id']??0)===(int)$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><div class="resolver-actions"><button class="ghost" type="button" id="keepUnknownTemporary">فقط در همین گزارش موقت بمانند</button><button class="primary" type="button" id="registerUnknownAccounts">در AccountSettings پنل ثبت شوند</button></div><div class="tiny">در حالت موقت Account ساخته نمی‌شود، اما پنل گزارش ثبت می‌شود تا کنترل همپوشانی همان روز ممکن باشد.</div></div></dialog>
<script>
(()=>{
let rows=<?=json_encode($draft['rows'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let editing=-1;
const n=v=>{const s=String(v??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/,/g,'');const x=Number(s);return Number.isFinite(x)?x:0};
const MONEY_FACTOR=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>;const fd=v=>(Number(v)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});const fm=v=>((Number(v)||0)/MONEY_FACTOR).toLocaleString('en-US',{maximumFractionDigits:0});const rateDisplay=v=>((Number(v)||0)/MONEY_FACTOR);const rateCanonical=v=>(Number(v)||0)*MONEY_FACTOR;
function calc(r){const mw=n(r.member_win),rate=n(r.rate),pct=n(r.loss_percent);let commission=0,received=0,paid=0;if(mw<0){const gross=Math.abs(mw)*rate;commission=gross*pct/100;received=gross-commission}else if(mw>0)paid=mw*rate;r.member_win=mw;r.rate=rate;r.loss_percent=pct;r.commission=commission;r.received=received;r.paid=paid;return r}
function totals(){return rows.reduce((t,r)=>{calc(r);t.received+=r.received;t.paid+=r.paid;t.commission+=r.commission;return t},{received:0,paid:0,commission:0})}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function render(){const body=document.getElementById('previewRows');body.innerHTML=rows.map((r,i)=>{calc(r);const unresolved=!r.account_id&&!r.unknown_confirmed;return `<tr class="${!r.account_id?'unknown-row':''} ${unresolved?'unresolved-row':''}"><td class="name-cell">${esc(r.name||r.username)}</td><td class="username-cell" dir="ltr">${esc(r.username)}</td><td class="comm-cell">${r.commission?fm(r.commission):''}</td><td>${r.member_win<0?fd(Math.abs(r.member_win)):''}</td><td class="recv-cell">${r.received?fm(r.received):''}</td><td>${r.member_win>0?fd(r.member_win):''}</td><td class="pay-cell">${r.paid?fm(r.paid):''}</td><td><button type="button" class="ghost row-edit" data-i="${i}">✎</button></td></tr>`}).join('');const t=totals(),net=t.received-t.paid,status=net>0?'برد سایت':net<0?'باخت سایت':'تسویه',cls=net>0?'site-win':net<0?'site-loss':'comm-cell';document.getElementById('previewTotals').innerHTML=`<div class="recv-cell"><span>دریافتی</span><b>${fm(t.received)}</b></div><div class="pay-cell"><span>پرداختی</span><b>${fm(t.paid)}</b></div><div class="comm-cell"><span>کمیسیون</span><b>${fm(t.commission)}</b></div><div class="${cls}"><span>${status}</span><b>${fm(Math.abs(net))}</b></div>`;body.querySelectorAll('.row-edit').forEach(b=>b.onclick=()=>openRow(Number(b.dataset.i)));const u=rows.filter(r=>!r.account_id&&!r.unknown_confirmed);const list=document.getElementById('unknownList');if(list)list.innerHTML=u.map(r=>`<div><b dir="ltr">${esc(r.username)}</b><span>${esc(r.name||'')}</span></div>`).join('')}
function openRow(i){editing=i;const r=rows[i];document.getElementById('rowEditorTitle').textContent=i<0?'افزودن ردیف':'ویرایش ردیف';document.getElementById('editUsername').value=r?.username||'';document.getElementById('editName').value=r?.name||'';document.getElementById('editOutcome').value=!r||r.member_win===0?'zero':r.member_win<0?'loss':'win';document.getElementById('editAmount').value=r?Math.abs(n(r.member_win)):'';document.getElementById('editRate').value=r?rateDisplay(r.rate):rateDisplay(<?=json_encode($draft['general_rate'])?>);document.getElementById('editPct').value=r?.loss_percent??<?=json_encode($draft['loss_percent'])?>;document.getElementById('editPanel').value=r?.panel_id||'';document.getElementById('editRegister').checked=!!r?.register_manual;document.getElementById('deleteRowBtn').style.display=i<0?'none':'';syncPct();openAppDialog('rowEditor')}
function syncPct(){const win=document.getElementById('editOutcome').value!=='loss';document.getElementById('editPct').disabled=win}
document.getElementById('editOutcome').onchange=syncPct;document.getElementById('addReportRowBtn').onclick=()=>openRow(-1);document.getElementById('saveRowBtn').onclick=()=>{const outcome=document.getElementById('editOutcome').value,amount=Math.abs(n(document.getElementById('editAmount').value));const old=editing>=0?rows[editing]:{};const r={...old,username:document.getElementById('editUsername').value.trim(),name:document.getElementById('editName').value.trim(),member_win:outcome==='loss'?-amount:outcome==='win'?amount:0,rate:rateCanonical(document.getElementById('editRate').value),loss_percent:n(document.getElementById('editPct').value),panel_id:document.getElementById('editPanel').value||null,register_manual:document.getElementById('editRegister').checked,unknown_confirmed:old.account_id?true:(old.unknown_confirmed||document.getElementById('editRegister').checked)};if(!r.username){appAlert('Username الزامی است.');return;}if(!r.name)r.name=r.username;if(editing>=0)rows[editing]=r;else rows.push(r);closeAppDialog('rowEditor');render()};document.getElementById('deleteRowBtn').onclick=async()=>{if(editing>=0&&await appConfirm('این ردیف حذف شود؟',{danger:true,confirmText:'حذف'})){rows.splice(editing,1);closeAppDialog('rowEditor');render()}};
function unresolved(){return rows.filter(r=>!r.account_id&&!r.unknown_confirmed)}function payload(){return JSON.stringify({rows:rows.map(calc),report_date_input:document.getElementById('previewReportDate').value.trim()})}
const sourceTotal=<?=json_encode($draft['source_member_win_total']??null)?>;
const sourceRawRowsTotal=<?=json_encode($draft['source_member_win_raw_rows_total']??null)?>;
const sourceRoundedRowsTotal=<?=json_encode($draft['source_member_win_rounded_rows_total']??null)?>;
const usdMicro=v=>{const a=n(v);return Math.sign(a)*Math.round(Math.abs(a)*1000000+1e-7)};
const fdPrec=v=>(Number(v)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:6});
const checkUsd=()=>{
 const btn=document.getElementById('checkUsdBalanceBtn'),box=document.getElementById('usdBalanceResult');
 // Compare six-decimal source amounts, without rounding member values to cents.
 const balanceMicro=-rows.reduce((sum,r)=>sum+usdMicro(r.member_win),0);
 const balance=balanceMicro/1000000;
 const hasSource=sourceTotal!==null&&Number.isFinite(Number(sourceTotal));
 const hasRaw=sourceRawRowsTotal!==null&&Number.isFinite(Number(sourceRawRowsTotal));
 const expected=hasSource?-Number(sourceTotal):null;
 const rawExpected=hasRaw?-Number(sourceRawRowsTotal):null;
 const excelDiffMicro=hasSource&&hasRaw?usdMicro(rawExpected)-usdMicro(expected):null;
 const previewDiffMicro=hasRaw?balanceMicro-usdMicro(rawExpected):null;
 const fallbackDiffMicro=hasSource?balanceMicro-usdMicro(expected):null;
 const differenceMicro=!hasSource?null:(excelDiffMicro!==null&&Math.abs(excelDiffMicro)>1?excelDiffMicro:(previewDiffMicro??fallbackDiffMicro));
 const difference=differenceMicro===null?null:differenceMicro/1000000;
 const state=!hasSource?'unknown':Math.abs(differenceMicro)<=1?'ok':'error';
 const palette={ok:['#d8f5e5','#11633e','#69bc91'],error:['#ffe2e2','#ab222e','#e69199'],unknown:['#fff3d9','#885b0c','#e6c276']}[state];
 btn.classList.remove('svo-usd-ok','svo-usd-error','svo-usd-unknown');btn.classList.add('svo-usd-'+state);btn.dataset.auditState=state;
 btn.textContent=state==='ok'?'✓ تراز تأیید شد: '+fd(balance)+' دلار':state==='error'?'✕ مغایرت: '+fdPrec(Math.abs(difference))+' دلار':'! جمع فایل مادر در دسترس نیست';
 btn.style.setProperty('background-color',palette[0],'important');btn.style.setProperty('color',palette[1],'important');btn.style.setProperty('border','1px solid '+palette[2],'important');
 box.className='svo-usd-feedback'+(state==='error'?' svo-usd-feedback-error':'');
 if(state==='error'){
   if(excelDiffMicro!==null&&Math.abs(excelDiffMicro)>1){
     box.textContent='جمع خام ردیف‌های اکسل: '+fdPrec(rawExpected)+' دلار | Grand Total اکسل: '+fdPrec(expected)+' دلار | اختلاف واقعی: '+fdPrec(Math.abs(excelDiffMicro/1000000))+' دلار';
   }else if(hasRaw){
     box.textContent='تراز پیش‌نمایش: '+fdPrec(balance)+' دلار | جمع خام فایل: '+fdPrec(rawExpected)+' دلار | اختلاف واقعی: '+fdPrec(Math.abs(previewDiffMicro/1000000))+' دلار';
   }else{
     box.textContent='تراز پیش‌نمایش: '+fdPrec(balance)+' دلار | Grand Total اکسل: '+fdPrec(expected)+' دلار | اختلاف: '+fdPrec(Math.abs(difference))+' دلار';
   }
   box.hidden=false;box.style.display='block';
 }else if(state==='unknown'){
   box.textContent='تراز محاسبه‌شده: '+fd(balance)+' دلار؛ Grand Total فایل مادر برای تطبیق موجود نیست.';box.hidden=false;box.style.display='block';
 }else{box.textContent='';box.hidden=true;box.style.display='none'}
 return difference;
};
const resetUsd=()=>{
 const btn=document.getElementById('checkUsdBalanceBtn'),box=document.getElementById('usdBalanceResult');if(!btn)return;
 btn.classList.remove('svo-usd-ok','svo-usd-error','svo-usd-unknown');delete btn.dataset.auditState;
 btn.style.removeProperty('background-color');btn.style.removeProperty('color');btn.style.removeProperty('border');
 btn.textContent='کنترل تراز دلاری';
 if(box){box.textContent='';box.hidden=true;box.style.display='none'}
};
document.getElementById('checkUsdBalanceBtn').onclick=checkUsd;
// Editing a row invalidates the previous audit until the user checks again.
const usdRows=document.getElementById('previewRows');if(usdRows)new MutationObserver(resetUsd).observe(usdRows,{childList:true});const resolveBtn=document.getElementById('resolveUnknownBtn');if(resolveBtn)resolveBtn.onclick=()=>{render();openAppDialog('unknownResolver')};function resolveUnknown(register){const pid=document.getElementById('unknownPanel').value;if(!pid){appAlert('پنل این گزارش را انتخاب کن.');return;}rows=rows.map(r=>!r.account_id&&!r.unknown_confirmed?{...r,panel_id:pid,register_manual:register,unknown_confirmed:true}:r);closeAppDialog('unknownResolver');render()}const keepBtn=document.getElementById('keepUnknownTemporary');if(keepBtn)keepBtn.onclick=()=>resolveUnknown(false);const regBtn=document.getElementById('registerUnknownAccounts');if(regBtn)regBtn.onclick=()=>resolveUnknown(true);const submitUsdReport=(reason='')=>{document.getElementById('usdAuditReasonField').value=reason;document.getElementById('finalDraftJson').value=payload();document.getElementById('finalizeReportForm').submit()};
document.getElementById('usdExceptionConfirm').onclick=()=>{const reason=document.getElementById('usdExceptionReason').value.trim();if(reason.length<8){appAlert('علت مغایرت را با حداقل ۸ نویسه وارد کن.');return}submitUsdReport(reason)};
document.getElementById('finalizeReportBtn').onclick=()=>{const diff=checkUsd();if(unresolved().length){render();openAppDialog('unknownResolver');return}if(diff!==null&&Math.abs(diff)>0.000001){document.getElementById('usdExceptionDetails').textContent='اختلاف تراز دلاری: '+fdPrec(Math.abs(diff))+' دلار. در صورت تأیید، علت آن در دیتابیس و هشدار ترانسفر ثبت می‌شود.';openAppDialog('usdExceptionDialog');return}submitUsdReport()};document.getElementById('backToEntryBtn').onclick=()=>{document.getElementById('backDraftJson').value=payload();document.getElementById('backDraftForm').submit()};render();
})();
</script>
