rtImagePreview" class="svo-report-image-preview" alt="پیش‌نمایش تصویر گزارش" hidden></div></dialog><script>
const REPORT_THEME=<?=json_encode(['recv'=>SettingsService::themeFill($uiSettings['theme_recv'],$uiSettings),'pay'=>SettingsService::themeFill($uiSettings['theme_pay'],$uiSettings),'comm'=>SettingsService::themeFill($uiSettings['theme_comm'],$uiSettings),'siteWin'=>SettingsService::themeFill($uiSettings['theme_site_win']??$uiSettings['theme_pay'],$uiSettings),'siteLoss'=>SettingsService::themeFill($uiSettings['theme_site_loss']??$uiSettings['theme_recv'],$uiSettings)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const REPORT_DEFAULT_TOTALS=<?=json_encode($reportData['totals'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const REPORT_FACTOR=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>;const REPORT_LOCALE=<?=json_encode($uiSettings['digit_mode']==='fa'?'fa-IR':'en-US')?>;const REPORT_UNIT=<?=json_encode(SettingsService::moneyUnit($uiSettings),JSON_UNESCAPED_UNICODE)?>;const REPORT_IS_CUMULATIVE=<?=json_encode($rf['type']==='cumulative')?>;const REPORT_IMAGE_WIDTHS=<?=json_encode(in_array($reportData['type'],['detail','customer_detail'],true)?[56,262,182,130,152,154,154]:[])?>;const REPORT_IMAGE_TITLE=<?=json_encode(ReportHeading626::title($reportData),JSON_UNESCAPED_UNICODE)?>;const REPORT_IMAGE_SUBTITLE=<?=json_encode(ReportHeading626::subtitle($reportData, SettingsService::moneyUnit($uiSettings)),JSON_UNESCAPED_UNICODE)?>;const REPORT_IMAGE_PERIOD=<?=json_encode(ReportHeading626::period($reportData),JSON_UNESCAPED_UNICODE)?>;let reportImageBlob=null,reportImageName='accounting-report.png';
function reportDigitsToEn(value){return String(value??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/,/g,'').replace(/[^0-9+\-.]/g,'').trim()}
function reportParseAmount(value){const cleaned=reportDigitsToEn(value);if(cleaned===''||cleaned==='+'||cleaned==='-'||cleaned==='.')return 0;const num=Number(cleaned);return Number.isFinite(num)?num:0}
function reportFmt(value){return (Number(value||0)/REPORT_FACTOR).toLocaleString(REPORT_LOCALE,{maximumFractionDigits:0})}
function reportCollectRows(selectedOnly=false){const table=document.getElementById('reportDataTable');if(!table)return[];const rows=[];table.querySelectorAll('tr').forEach(tr=>{const inBody=tr.parentElement&&tr.parentElement.tagName==='TBODY';if(selectedOnly&&inBody){const check=tr.querySelector('input[name="ids[]"]');if(check&&!check.checked)return;}const cells=[...tr.cells].filter(td=>!td.classList.contains('no-image')&&!td.classList.contains('no-output')&&!td.classList.contains('report-view-head')&&!td.classList.contains('report-actions-cell')&&!td.querySelector('input[type=checkbox]')).map(td=>({text:td.innerText.trim(),recv:td.classList.contains('recv-cell'),pay:td.classList.contains('pay-cell'),comm:td.classList.contains('comm-cell'),mwPos:td.classList.contains('svo-mw-positive'),mwNeg:td.classList.contains('svo-mw-negative'),siteWin:td.classList.contains('site-win'),siteLoss:td.classList.contains('site-loss'),head:td.tagName==='TH'}));if(cells.length)rows.push(cells)});return rows}
function reportSelectedTotals(){const total={received:0,paid:0,commission:0,net:0,reports:0};document.querySelectorAll('#reportDataTable tbody tr').forEach(tr=>{const check=tr.querySelector('input[name="ids[]"]');if(!check||!check.checked)return;total.reports++;const recv=tr.querySelector('td.recv-cell');const pay=tr.querySelector('td.pay-cell');const net=[...tr.cells].find(td=>td.classList.contains('site-win')||td.classList.contains('site-loss')||td.classList.contains('comm-cell'));total.received+=reportParseAmount(recv?.innerText)*REPORT_FACTOR;total.paid+=reportParseAmount(pay?.innerText)*REPORT_FACTOR;let netShown=reportParseAmount(net?.innerText);if(net?.classList.contains('site-loss')||String(net?.innerText||'').trim().startsWith('-'))netShown=-Math.abs(netShown);else netShown=Math.abs(netShown);total.net+=netShown*REPORT_FACTOR});if(total.reports&&Math.abs(total.net)<0.0001)total.net=total.received-total.paid;return total}
function reportCanvasCreate(width,height,scale){const c=document.createElement('canvas');c.width=Math.round(width*scale);c.height=Math.round(height*scale);const ctx=c.getContext('2d');if(!ctx)throw Error('مرورگر از ساخت تصویر پشتیبانی نمی‌کند.');ctx.setTransform(scale,0,0,scale,0,0);ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);return {canvas:c,ctx}}
function reportCanvasPng(c){return SvoImage617.encode(c,{type:'png'})}
async function makeReportImage(opts={}){
try{
const selectedOnly=!!opts.selectedOnly,raw=reportCollectRows(selectedOnly);
if(!raw.length||(selectedOnly&&raw.length<2)){appAlert('حداقل یک گزارش را انتخاب کن.');return null}
if(raw.some(r=>r.length!==(raw[0]?.length??0))){appAlert('ستون‌های خروجی تصویر هم‌تراز نیستند؛ خروجی ساخته نشد.');return null}
if(raw.length>351){appAlert('این خروجی بیش از ۳۵۰ ردیف دارد؛ برای نسخه کامل از PDF استفاده کن.');return null}
if(document.fonts)await document.fonts.ready;
const cols=Math.max(...raw.map(r=>r.length)),baseWidths=REPORT_IMAGE_WIDTHS.length?[...REPORT_IMAGE_WIDTHS]:[];
if(!baseWidths.length){for(let k=0;k<cols;k++)baseWidths.push(Math.max(138,Math.floor(1680/cols)))}
const widths=baseWidths,tableW=widths.reduce((s,v)=>s+v,0),pad=24,rowH=54,titleH=140,footerH=210;
const w=pad*2+tableW,h=titleH+raw.length*rowH+footerH;
const scale=Math.min(1.95,14500/Math.max(w,h),Math.sqrt(28000000/(w*h)));
const {canvas:c,ctx:x}=reportCanvasCreate(w,h,Math.max(1.45,scale));
const title=opts.title||REPORT_IMAGE_TITLE;
const subtitle=opts.subtitle||REPORT_IMAGE_SUBTITLE;
x.fillStyle='#fff';x.fillRect(0,0,w,h);x.fillStyle='#111';x.textAlign='center';x.textBaseline='middle';x.font='900 36px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(title,w/2,38,w-50);x.font='900 24px Vazirmatn,Tahoma,Arial,sans-serif';x.fillStyle='#1e4268';x.fillText(REPORT_IMAGE_PERIOD||subtitle,w/2,78,w-50);x.font='700 16px Vazirmatn,Tahoma,Arial,sans-serif';x.fillStyle='#64748b';x.fillText('واحد مبلغ: '+REPORT_UNIT,w/2,111,w-50);
const drawRow=(row,yy)=>{let right=pad+tableW;for(let i=0;i<cols;i++){const cw=widths[i];right-=cw;const cell=row[i]||{text:''};x.fillStyle=cell.recv?REPORT_THEME.recv:cell.pay?REPORT_THEME.pay:cell.comm?REPORT_THEME.comm:cell.siteWin?REPORT_THEME.siteWin:cell.siteLoss?REPORT_THEME.siteLoss:cell.head?'#e2e8f0':'#fff';x.fillRect(right,yy,cw,rowH);x.strokeStyle='#111827';x.lineWidth=1.4;x.strokeRect(right,yy,cw,rowH);x.fillStyle=cell.mwPos?'#1557ac':cell.mwNeg?'#b91c1c':'#111';x.font=(cell.head?'800 18px':'700 16px')+' Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(cell.text,right+cw/2,yy+rowH/2,cw-12)}};
let yy=titleH;raw.forEach(row=>{drawRow(row,yy);yy+=rowH});
const totals=selectedOnly&&REPORT_IS_CUMULATIVE?reportSelectedTotals():{...REPORT_DEFAULT_TOTALS,reports:raw.length-1};const net=Number(totals.net)||0;
const boxes=(REPORT_IS_CUMULATIVE?[{label:'تعداد گزارش',value:totals.reports||Math.max(0,raw.length-1),color:'#eef2ff',plain:true},{label:'جمع پرداختی',value:totals.paid,color:REPORT_THEME.pay},{label:'جمع دریافتی',value:totals.received,color:REPORT_THEME.recv}]:[{label:'جمع پرداختی',value:totals.paid,color:REPORT_THEME.pay},{label:'جمع کمیسیون',value:totals.commission,color:REPORT_THEME.comm},{label:'جمع دریافتی',value:totals.received,color:REPORT_THEME.recv}]);
const boxY=titleH+raw.length*rowH+24;const bw=(w-pad*2)/3;boxes.forEach((b,i)=>{x.fillStyle=b.color;x.fillRect(pad+i*bw,boxY,bw,60);x.strokeStyle='#111827';x.strokeRect(pad+i*bw,boxY,bw,60);x.fillStyle='#111';x.font='800 19px Vazirmatn,Tahoma,Arial,sans-serif';const value=b.plain?Number(b.value||0).toLocaleString(REPORT_LOCALE):reportFmt(b.value);x.fillText(`${b.label}: ${value}`,pad+i*bw+bw/2,boxY+31,bw-12)});
x.fillStyle=net>0?REPORT_THEME.siteWin:net<0?REPORT_THEME.siteLoss:REPORT_THEME.comm;x.fillRect(pad,boxY+76,w-pad*2,72);x.strokeStyle='#111827';x.strokeRect(pad,boxY+76,w-pad*2,72);x.fillStyle='#111';x.font='900 24px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(`${net>0?'برد سایت':net<0?'باخت سایت':'تسویه'}: ${reportFmt(Math.abs(net))}`,w/2,boxY+112,w-60);
reportImageBlob=await reportCanvasPng(c);reportImageName=opts.filename||'accounting-report.png';const url=URL.createObjectURL(reportImageBlob);const a=document.getElementById('reportImageDownload');if(a.dataset.url)URL.revokeObjectURL(a.dataset.url);a.dataset.url=url;a.href=url;a.download=reportImageName;document.getElementById('reportShareBox').classList.remove('hidden');const preview=document.getElementById('reportImagePreview');if(preview){preview.src=url;preview.hidden=false}const st=document.getElementById('reportImageStatus');if(st)st.textContent='PNG آماده است. برای ارسال مستقیم «اشتراک» را بزن؛ اگر پیام‌رسان کیفیت را کم کرد، فایل را به‌صورت Document بفرست.';const dialog=document.getElementById('svoReportImageDialog');if(dialog&&!dialog.open)dialog.showModal();return reportImageBlob
}catch(error){console.error('Report image error:',error);(window.appAlert||window.alert)(error?.message||'ساخت تصویر انجام نشد.');return null}}
async function copyReportTable622(){try{if(!reportImageBlob)throw Error('ابتدا عکس جدول را بساز.');await SvoImage617.copyImage(()=>reportImageBlob,'table.png');svoCopyToast('تصویر کپی شد.')}catch(e){appAlert(e.message)}}
function shareReportImage(){if(!reportImageBlob){window.appAlert?appAlert('عکس هنوز آماده نیست. ابتدا تصویر گزارش را بساز.'):alert('عکس هنوز آماده نیست.');return}const file=new File([reportImageBlob],reportImageName||'accounting-report.png',{type:'image/png'});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){try{navigator.share({files:[file],title:REPORT_IMAGE_TITLE}).catch(e=>{if(e.name!=='AbortError')reportImageShareFallback()});return}catch(e){}}reportImageShareFallback()}
function reportImageShareFallback(){const a=document.getElementById('reportImageDownload');if(a?.href){a.click();window.appAlert?appAlert('مرورگر اشتراک مستقیم فایل را پشتیبانی نمی‌کند؛ PNG دانلود شد. برای جلوگیری از افت کیفیت آن را به‌صورت فایل/Document ارسال کن.'):alert('عکس دریافت شد؛ آن را به‌صورت فایل بفرست.')}}
</script>

