<script>(()=>{const sel=document.getElementById('moneyScaleSelect');if(!sel)return;const fields=[document.getElementById('settingsGeneralRate'),document.getElementById('settingsSpecialRate')];const factor=s=>s==='trim3'?1000:s==='trim4'?10000:1;let prev=sel.dataset.currentScale||sel.value;sel.addEventListener('change',()=>{const oldF=factor(prev),newF=factor(sel.value);for(const el of fields){if(!el)continue;const raw=String(el.value||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/,/g,'');const n=Number(raw);if(Number.isFinite(n))el.value=String(Math.round((n*oldF/newF)*1e6)/1e6)}prev=sel.value});})();</script>

