<script>
function openAppDialog(id){const d=document.getElementById(id);if(d&&d.showModal)d.showModal()}
function closeAppDialog(id){const d=document.getElementById(id);if(d)d.close()}
document.addEventListener('click',e=>{const d=e.target;if(d instanceof HTMLDialogElement&&e.target===d)d.close()});
</script><script>
(function(){
 const svg=document.getElementById('dashboardTrendChart'),raw=window.DASHBOARD_CHART||[],meta=window.DASHBOARD_META||{factor:1,unit:'تومان',digits:'fa'},empty=document.getElementById('dashboardTrendEmpty'),legend=document.getElementById('trendLegend'),tip=document.getElementById('trendTooltip');
 if(!svg)return;
 const buttons=[...document.querySelectorAll('.trend-periods [data-days]')],colors=['#0f9d7a','#e27a22','#2878d4','#9c4dcc','#d54b8c','#6874d8'];
 const locale=meta.digits==='en'?'en-US':'fa-IR',money=n=>(Number(n||0)/(Number(meta.factor)||1)).toLocaleString(locale,{maximumFractionDigits:0});
 const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
 const statusText=v=>v>0?'برد سایت':v<0?'باخت سایت':'تسویه';
 function showTip(e,label,date,value){
   const cls=value>0?'win':value<0?'loss':'';tip.className='trend-tooltip '+cls;
   tip.innerHTML=`<b>${esc(label)}</b><span>${esc(date)}</span><br><strong>${statusText(value)}: ${money(Math.abs(value))} ${esc(meta.unit||'')}</strong>`;tip.classList.remove('hidden');
   requestAnimationFrame(()=>{const wrap=svg.parentElement,wb=wrap.getBoundingClientRect(),db=e.currentTarget.getBoundingClientRect(),tw=tip.offsetWidth||170,th=tip.offsetHeight||62;let left=(db.left+db.width/2)-wb.left-tw/2,top=db.top-wb.top-th-10;left=Math.max(8,Math.min(left,wb.width-tw-8));if(top<8)top=Math.min(wb.height-th-8,(db.bottom-wb.top)+10);tip.style.left=left+'px';tip.style.top=Math.max(8,top)+'px';});
 }
 function hideTip(){tip?.classList.add('hidden')}
 function cumulative(vals){let sum=0;return vals.map(v=>(sum+=Number(v)||0));}
 function render(days){
   buttons.forEach(b=>b.classList.toggle('active',Number(b.dataset.days)===days));
   const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-days+1);
   const data=raw.filter(r=>{const d=new Date(String(r.date)+'T00:00:00');return !Number.isNaN(d.getTime())&&d>=cutoff});
   if(!data.length){svg.innerHTML='';legend.innerHTML='';empty?.classList.remove('hidden');document.getElementById('trendDirection').textContent='روند کل —';return}empty?.classList.add('hidden');
   let win=0,loss=0,net=0;for(const r of data){const n=Number(r.net)||0;net+=n;if(n>0)win+=n;else if(n<0)loss+=Math.abs(n)}const total=win+loss||1;
   document.getElementById('trendWinRatio').textContent=`برد سایت ${Math.round(win/total*100)}٪`;
   document.getElementById('trendLossRatio').textContent=`باخت سایت ${Math.round(loss/total*100)}٪`;
   document.getElementById('trendNet').textContent=`خالص ${statusText(net)} ${money(Math.abs(net))} ${meta.unit||''}`;
   const direction=document.getElementById('trendDirection');direction.textContent=`روند کل: ${statusText(net)} ${money(Math.abs(net))} ${meta.unit||''}`;direction.className='trend-direction '+(net>0?'win':net<0?'loss':'');
   const sums={};data.forEach(r=>sums[r.company]=(sums[r.company]||0)+Math.abs(Number(r.net)||0));const companies=Object.keys(sums).sort((a,b)=>sums[b]-sums[a]).slice(0,6);
   const dates=[...new Set(data.map(r=>r.date))].sort(),displayByDate=Object.fromEntries(data.map(r=>[r.date,r.display||r.date]));
   const bucket={},overall={};for(const r of data){const n=Number(r.net)||0;overall[r.date]=(overall[r.date]||0)+n;if(companies.includes(r.company)){const k=r.company+'|'+r.date;bucket[k]=(bucket[k]||0)+n}}
   const overallDaily=dates.map(d=>overall[d]||0),overallVals=cumulative(overallDaily);
   const series=companies.map((name,i)=>{const daily=dates.map(d=>bucket[name+'|'+d]||0),vals=cumulative(daily);return{name,color:colors[i%colors.length],vals,final:vals.at(-1)||0}});
   const W=760,H=270,pL=62,pR=28,pT=20,pB=40,all=[...overallVals,...series.flatMap(s=>s.vals)],mn=Math.min(0,...all),mx=Math.max(0,...all),span=Math.max(1,mx-mn),x=i=>pL+i*((W-pL-pR)/Math.max(1,dates.length-1)),y=v=>pT+(mx-v)*(H-pT-pB)/span,zero=y(0);
   const ticks=4;let html=`<defs><linearGradient id="overallArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--p)" stop-opacity=".30"/><stop offset="100%" stop-color="var(--p)" stop-opacity=".03"/></linearGradient></defs>`;
   for(let i=0;i<=ticks;i++){const value=mx-(span*i/ticks),yy=y(value);html+=`<line x1="${pL}" y1="${yy}" x2="${W-pR}" y2="${yy}" class="trend-grid"/><text x="${pL-8}" y="${yy+3}" text-anchor="end" class="trend-axis-label">${money(value)}</text>`}
   html+=`<line x1="${pL}" y1="${zero}" x2="${W-pR}" y2="${zero}" class="trend-zero"/><line x1="${pL}" y1="${pT}" x2="${pL}" y2="${H-pB}" class="trend-axis"/>`;
   const overallPts=overallVals.map((v,i)=>`${x(i)},${y(v)}`).join(' '),areaPts=`${pL},${zero} ${overallPts} ${x(dates.length-1)},${zero}`;html+=`<polygon points="${areaPts}" class="trend-overall-area"/><polyline points="${overallPts}" class="trend-overall-line"/>`;
   series.forEach(sr=>{const pts=sr.vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');html+=`<polyline points="${pts}" class="trend-company-line" style="stroke:${sr.color}"/>`;sr.vals.forEach((v,i)=>{html+=`<circle cx="${x(i)}" cy="${y(v)}" r="4.5" style="fill:${sr.color}" class="trend-company-dot" data-label="${esc(sr.name)}" data-date="${esc(displayByDate[dates[i]]||dates[i])}" data-value="${v}"></circle>`})});
   overallVals.forEach((v,i)=>{html+=`<circle cx="${x(i)}" cy="${y(v)}" r="5" class="trend-overall-dot" data-label="مجموع کل شرکت‌ها" data-date="${esc(displayByDate[dates[i]]||dates[i])}" data-value="${v}"></circle>`});
   const labelEvery=Math.max(1,Math.ceil(dates.length/6));dates.forEach((d,i)=>{if(i%labelEvery===0||i===dates.length-1){const lab=String(displayByDate[d]||d).slice(-5);html+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle" class="trend-label">${esc(lab)}</text>`}});svg.innerHTML=html;
   const overallFinal=overallVals.at(-1)||0;legend.innerHTML=`<span class="overall"><i></i>مجموع کل: ${statusText(overallFinal)} ${money(Math.abs(overallFinal))}</span>`+series.map(sr=>`<span><i style="background:${sr.color}"></i>${esc(sr.name)}: ${statusText(sr.final)} ${money(Math.abs(sr.final))}</span>`).join('');
   svg.querySelectorAll('[data-value]').forEach(dot=>{const fn=e=>showTip(e,dot.dataset.label,dot.dataset.date,Number(dot.dataset.value));dot.addEventListener('mouseenter',fn);dot.addEventListener('focus',fn);dot.addEventListener('click',fn);dot.addEventListener('mouseleave',hideTip);dot.setAttribute('tabindex','0')});
 }
 buttons.forEach(b=>b.addEventListener('click',()=>render(Number(b.dataset.days)||30)));render(30);
})();;
(function(){
 const clean=v=>String(v??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/,/g,'').trim();
 const fmt=v=>{const s=clean(v);if(!s||!/^[-+]?\d*(?:\.\d*)?$/.test(s))return v;const parts=s.split('.'),sign=parts[0].startsWith('-')?'-':'';let whole=parts[0].replace(/^[-+]/,'');whole=whole.replace(/^0+(?=\d)/,'')||'0';whole=whole.replace(/\B(?=(\d{3})+(?!\d))/g,',');return sign+whole+(parts.length>1?'.'+parts[1]:'')};
 document.querySelectorAll('input.grouped-number').forEach(el=>{el.value=fmt(el.value);el.addEventListener('input',()=>{const pos=el.selectionStart,end=el.selectionEnd,before=el.value;el.value=fmt(el.value);if(pos!==null){const delta=el.value.length-before.length;try{el.setSelectionRange(Math.max(0,pos+delta),Math.max(0,(end??pos)+delta))}catch(e){}}});});
})();
</script><?php if(in_array($page,['login','recover'],true) && LoginGuard630::enabled()):?><script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script><?php endif; ?>
<script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}let deferredPwaPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPwaPrompt=e;document.getElementById('pwaInstallBtn')?.classList.remove('hidden')});document.addEventListener('click',async e=>{if(e.target.closest?.('#pwaInstallBtn')&&deferredPwaPrompt){deferredPwaPrompt.prompt();await deferredPwaPrompt.userChoice;deferredPwaPrompt=null;document.getElementById('pwaInstallBtn')?.classList.add('hidden')}});</script></body></html>
